import React, { useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [features, setFeatures] = useState({
    PM2_5: 35,
    CO: 0.6,
    NO2: 20,
    NH3: 30,
    O3: 60,
    Temp: 25,
    Humidity: 50,
    Pressure: 1013
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handlePredict = async () => {
    try {
      const response = await axios.post('http://localhost:5000/predict', {
        'PM2.5': features.PM2_5,
        'CO': features.CO,
        'NO2': features.NO2,
        'NH3': features.NH3,
        'O3': features.O3,
        'Temp': features.Temp,
        'Humidity': features.Humidity,
        'Pressure': features.Pressure
      });
      setResult(response.data.prediction);
    } catch (error) {
      console.error("Prediction error:", error);
      setResult("Error connecting to server");
    }
  };

  return (
    <div style={{ maxWidth: '500px', margin: '40px auto', padding: '20px', backgroundColor: '#f3f3f3', borderRadius: '10px', fontFamily: 'Arial' }}>
      <h2 style={{ textAlign: 'center' }}>Enter Sensor Data</h2>
      {Object.keys(features).map((key) => (
        <div key={key} style={{ marginBottom: '12px' }}>
          <label style={{ display: 'inline-block', width: '100px' }}>{key}:</label>
          <input
            type="number"
            name={key}
            value={features[key]}
            onChange={handleChange}
            style={{ padding: '5px', width: '120px' }}
          />
        </div>
      ))}
      <button
        onClick={handlePredict}
        style={{
          padding: '10px 20px',
          backgroundColor: '#0097a7',
          color: 'white',
          border: 'none',
          borderRadius: '6px',
          cursor: 'pointer',
          marginTop: '10px'
        }}
      >
        Predict EAQI
      </button>
      {result && (
        <h3 style={{ marginTop: '20px', color: '#333', textAlign: 'center' }}>
          Prediction: {result}
        </h3>
      )}
    </div>
  );
};

export default Dashboard;
